package io.knowledgebrain.collaboration;
import java.util.*;import javax.sql.DataSource;import java.time.*;import java.util.concurrent.*;import org.junit.jupiter.api.*;import org.junit.jupiter.api.condition.EnabledIfEnvironmentVariable;import org.springframework.web.server.ResponseStatusException;import static org.junit.jupiter.api.Assertions.*;
@EnabledIfEnvironmentVariable(named="BRAIN_TEST_COLLABORATION_DATABASE_URL",matches=".+")
class CourseGradingQueueIntegrationTest {
 SubmissionGradeStoreIntegrationTest f;CourseGradingQueueStore store;CourseStore courses;UUID course;
 record Bound(CourseStore store,UUID id) {}
 static Bound bind(DataSource source,UUID group,UUID space,UUID study,UUID owner,String trace){var store=new CourseStore(source,Clock.systemUTC());var c=store.create(group,space,owner,UUID.randomUUID().toString().replace("-",""),"Owner grading Course","Shared",trace).course();store.curriculum(group,space,c.courseId(),owner,1,List.of(study),trace);return new Bound(store,c.courseId());}GradeRetractionStore markers;
 @BeforeEach void setup(){f=new SubmissionGradeStoreIntegrationTest();f.setup();var bound=bind(f.f.f.source,f.f.group,f.f.space,f.f.study,f.f.f.owner,f.f.f.trace);courses=bound.store();course=bound.id();store=new CourseGradingQueueStore(f.f.f.source,courses);markers=new GradeRetractionStore(f.f.f.source,f.f.parent.store,f.f.store,Clock.systemUTC());}
 CourseGradingQueueStore.Page list(String filter,UUID after,int limit){return store.list(f.f.group,f.f.space,course,f.f.f.owner,after,limit,filter);}
 CourseGradingQueueStore.Row row(){return list("ALL",null,100).items().stream().filter(v->v.submissionId().equals(f.answer.submissionId())).findFirst().orElseThrow();}
 GradeRetractionStore.Retraction mark(long target,long expected,String state){return markers.change(f.f.group,f.f.space,f.f.study,f.f.assignment,f.answer.submissionId(),f.f.f.owner,target,expected,new GradeRetractionInput(state,"PRIVATE annotation reason"),f.f.f.trace);}
 @Test void missingGradesAreMetadataOnlyAndReadsCreateNothing(){int events=f.f.f.jdbc.queryForObject("SELECT count(*) FROM outbox_event",Integer.class);var v=row();assertEquals("MISSING",v.gradingStatus());assertNull(v.gradeVersion());assertNull(v.gradedSubmissionVersion());assertEquals("NONE",v.gradeRetractionState());assertNull(v.retractionVersion());assertEquals(1,list("NEEDS_GRADING",null,20).items().size());assertTrue(list("CURRENT",null,20).items().isEmpty());var json=tools.jackson.databind.json.JsonMapper.builder().build().valueToTree(v);assertEquals(16,json.size());for(String key:List.of("score","reason","content","graderId","snapshot","audience"))assertFalse(json.has(key));assertEquals(events,f.f.f.jdbc.queryForObject("SELECT count(*) FROM outbox_event",Integer.class));assertNull(f.get(f.f.author,false).grade());}
 @Test void zeroScoreCountsAsCurrentAndResubmissionMakesOnlyOldAnswerGradeOutdated(){var grade=f.store.change(f.f.group,f.f.space,f.f.study,f.f.assignment,f.answer.submissionId(),f.f.f.owner,0,new SubmissionGradeInput(0,"PRIVATE zero-grade reason",1,2),f.f.f.trace);assertEquals(0,grade.score());assertEquals("CURRENT",row().gradingStatus());assertTrue(list("NEEDS_GRADING",null,20).items().isEmpty());assertEquals(1,list("CURRENT",null,20).items().size());f.f.submit(f.f.f.key(),1,2,"NEW PRIVATE ANSWER");assertEquals("OUTDATED",row().gradingStatus());assertEquals(2,row().version());assertEquals(1L,row().gradedSubmissionVersion());assertEquals(1,list("OUTDATED",null,20).items().size());assertTrue(list("CURRENT",null,20).items().isEmpty());f.change(1,2,"PRIVATE new-answer grade");assertEquals("CURRENT",row().gradingStatus());assertEquals(2L,row().gradeVersion());assertEquals(2L,row().gradedSubmissionVersion());}
 @Test void onlyLatestGradeVersionMarkerAffectsCurrentAnswerStatus(){f.change(0,1,"First grade");mark(1,0,"RETRACTED");assertEquals("RETRACTED",row().gradingStatus());assertEquals(1,list("RETRACTED",null,20).items().size());mark(1,1,"RESTORED");assertEquals("CURRENT",row().gradingStatus());assertEquals("RESTORED",row().gradeRetractionState());f.change(1,1,"New independently reviewed grade");mark(1,2,"RETRACTED");assertEquals("CURRENT",row().gradingStatus());assertEquals("NONE",row().gradeRetractionState());assertNull(row().retractionVersion());assertTrue(list("RETRACTED",null,20).items().isEmpty());mark(2,0,"RETRACTED");assertEquals("RETRACTED",row().gradingStatus());assertEquals(1L,row().retractionVersion());assertEquals(1,list("NEEDS_GRADING",null,20).items().size());mark(2,1,"RESTORED");assertEquals("CURRENT",row().gradingStatus());assertEquals(2L,row().retractionVersion());}
 @Test void withdrawnOldAnswerStaysOutdatedAndHistoricalMarkerCannotInvalidateNewGrade(){f.change(0,1,"First");f.f.submit(f.f.f.key(),1,2,"Second answer");mark(1,0,"RETRACTED");assertEquals("OUTDATED",row().gradingStatus());assertEquals("RETRACTED",row().gradeRetractionState());assertTrue(list("RETRACTED",null,20).items().isEmpty());assertEquals(1,list("NEEDS_GRADING",null,20).items().size());f.change(1,2,"Second grade");assertEquals("CURRENT",row().gradingStatus());assertEquals("NONE",row().gradeRetractionState());}
 @Test void ownerSelfSubmissionIsExcludedWhileLegacyCatalogRemainsUnchanged(){var self=f.f.store.submit(f.f.group,f.f.space,f.f.study,f.f.assignment,f.f.f.owner,0,2,f.f.f.key(),"Owner self answer",f.f.f.trace).submission();assertEquals(1,list("ALL",null,20).items().size());assertFalse(list("ALL",null,20).items().stream().anyMatch(v->v.submissionId().equals(self.submissionId())));assertEquals(2,new SubmissionReviewStore(f.f.f.source,f.f.parent.store).list(f.f.group,f.f.space,f.f.study,f.f.assignment,null,20,"ALL").items().size());assertFalse(f.store.get(f.f.group,f.f.space,f.f.study,f.f.assignment,self.submissionId(),f.f.f.owner,true).canWrite());}
 @Test void unknownOrMissingMarkerStateIsNeverReportedAsCurrent(){f.change(0,1,"Grade");var marker=mark(1,0,"RETRACTED");String saved=f.f.f.jdbc.queryForObject("SELECT snapshot::text FROM grade_retraction WHERE retraction_id=?",String.class,marker.retractionId());try{for(String expression:List.of("jsonb_set(snapshot,'{state}','\"INVALID\"')","snapshot-'state'")){f.f.f.jdbc.update("UPDATE grade_retraction SET snapshot="+expression+" WHERE retraction_id=?",marker.retractionId());assertEquals("UNAVAILABLE",row().gradingStatus());assertEquals("UNKNOWN",row().gradeRetractionState());assertTrue(list("CURRENT",null,20).items().isEmpty());assertEquals(1,list("UNAVAILABLE",null,20).items().size());assertEquals(1,list("NEEDS_GRADING",null,20).items().size());}}finally{f.f.f.jdbc.update("UPDATE grade_retraction SET snapshot=?::jsonb WHERE retraction_id=?",saved,marker.retractionId());}}
 @Test void stableKeysetAppliesGradePredicateBeforeLimitAcrossManyAuthors(){for(int n=0;n<24;n++){var sub=f.f.store.submit(f.f.group,f.f.space,f.f.study,f.f.assignment,f.f.f.ids.next(),0,2,f.f.f.key(),"Private answer "+n,f.f.f.trace).submission();if(n%2==0)f.store.change(f.f.group,f.f.space,f.f.study,f.f.assignment,sub.submissionId(),f.f.f.owner,0,new SubmissionGradeInput(0,"PRIVATE reason",1,2),f.f.f.trace);}assertEquals(25,list("ALL",null,100).items().size());assertEquals(12,list("CURRENT",null,100).items().size());assertEquals(13,list("NEEDS_GRADING",null,100).items().size());var expected=list("CURRENT",null,100).items().stream().map(CourseGradingQueueStore.Row::submissionId).toList();var seen=new ArrayList<UUID>();UUID after=null;do{var p=list("CURRENT",after,3);assertTrue(p.items().size()<=3);seen.addAll(p.items().stream().map(CourseGradingQueueStore.Row::submissionId).toList());after=p.nextAfter();}while(after!=null);assertEquals(expected,seen);assertEquals(12,new HashSet<>(seen).size());}
 @Test void exactCourseScopeEmptyCurriculumActorCursorAndFiltersStayBounded(){f.status(404,()->store.list(f.f.f.ids.next(),f.f.space,course,f.f.f.owner,null,20,"ALL"));f.status(404,()->store.list(f.f.group,f.f.f.ids.next(),course,f.f.f.owner,null,20,"ALL"));f.status(404,()->store.list(f.f.group,f.f.space,f.f.f.ids.next(),f.f.f.owner,null,20,"ALL"));var empty=courses.create(f.f.group,f.f.space,f.f.f.owner,f.f.f.key(),"Empty Course","Shared",f.f.f.trace).course();assertTrue(store.list(f.f.group,f.f.space,empty.courseId(),f.f.f.owner,null,20,"ALL").items().isEmpty());for(String filter:List.of("all","HAS_FEEDBACK","CURRENT' OR TRUE--",""))f.status(400,()->list(filter,null,20));for(int limit:List.of(0,101))f.status(400,()->list("ALL",null,limit));}
 @Test void closedArchivedReadsPreserveOriginalGradeFeedbackAndAudit(){var grade=f.change(0,1,"Grade");var marker=mark(1,0,"RETRACTED");f.f.parent.store.state(f.f.group,f.f.space,f.f.study,f.f.assignment,f.f.f.owner,2,"CLOSED",f.f.f.trace);f.f.parent.store.state(f.f.group,f.f.space,f.f.study,f.f.assignment,f.f.f.owner,3,"RETIRED",f.f.f.trace);f.f.parent.parent.store.state(f.f.group,f.f.space,f.f.study,f.f.f.owner,1,"RETIRED",f.f.f.trace);int count=f.f.f.jdbc.queryForObject("SELECT count(*) FROM outbox_event",Integer.class);for(var filter:CourseGradingQueueStore.FILTERS)list(filter,null,20);assertEquals("RETRACTED",row().gradingStatus());assertEquals(grade,f.get(f.f.author,false).grade());assertEquals(marker,markers.get(f.f.group,f.f.space,f.f.study,f.f.assignment,f.answer.submissionId(),f.f.author,false,1).retraction());assertEquals(count,f.f.f.jdbc.queryForObject("SELECT count(*) FROM outbox_event",Integer.class));}
 @Test void concurrentNewAnswerAndGradeAreReadAsOneStatementSnapshot()throws Exception{f.change(0,1,"First");try(var pool=Executors.newVirtualThreadPerTaskExecutor()){var barrier=new CyclicBarrier(2);var reads=pool.submit(()->{barrier.await();for(int n=0;n<30;n++){var v=row();assertTrue(v.gradedSubmissionVersion()<=v.version());if(v.gradingStatus().equals("CURRENT"))assertEquals(v.version(),v.gradedSubmissionVersion());else assertEquals("OUTDATED",v.gradingStatus());}return true;});var writes=pool.submit(()->{barrier.await();f.f.submit(f.f.f.key(),1,2,"New answer");return f.change(1,2,"New grade");});assertTrue(reads.get(20,TimeUnit.SECONDS));assertEquals(2,writes.get(20,TimeUnit.SECONDS).version());assertEquals("CURRENT",row().gradingStatus());}}

 @Test void rubricComputedZeroAndDirectModeUseTheSameQueueAndExactMarker(){var g=new RubricGradingStoreIntegrationTest();g.setup();var bound=bind(g.f.f.f.source,g.f.f.group,g.f.f.space,g.f.f.study,g.f.f.f.owner,g.f.f.f.trace);var q=new CourseGradingQueueStore(g.f.f.f.source,bound.store());var zero=g.change(0,g.input(0,0,"PRIVATE rubric zero"));assertEquals(0,zero.grade().score());var row=q.list(g.f.f.group,g.f.f.space,bound.id(),g.f.f.f.owner,null,20,"CURRENT").items().getFirst();assertEquals("CURRENT",row.gradingStatus());assertEquals(1L,row.gradeVersion());var markers=new GradeRetractionStore(g.f.f.f.source,g.f.f.store,g.submissions,Clock.systemUTC());markers.change(g.f.f.group,g.f.f.space,g.f.f.study,g.f.assignment,g.answer.submissionId(),g.f.f.f.owner,1,0,new GradeRetractionInput("RETRACTED","PRIVATE reason"),g.f.f.f.trace);assertEquals(1,q.list(g.f.f.group,g.f.f.space,bound.id(),g.f.f.f.owner,null,20,"NEEDS_GRADING").items().size());g.change(1,g.direct(0,"PRIVATE direct zero",1,2));var next=q.list(g.f.f.group,g.f.f.space,bound.id(),g.f.f.f.owner,null,20,"CURRENT").items().getFirst();assertEquals(2L,next.gradeVersion());assertEquals("NONE",next.gradeRetractionState());}

 UUID task(UUID study){var id=f.f.parent.store.create(f.f.group,f.f.space,study,f.f.f.owner,f.f.f.key(),"Task <script>","Shared",f.f.f.trace).assignment().assignmentId();f.f.parent.store.state(f.f.group,f.f.space,study,id,f.f.f.owner,1,"OPEN",f.f.f.trace);return id;}
 @Test void currentCurriculumLabelsAndArchivesPreserveOriginalVersionsWithoutEnrollment(){
  var b=f.f.parent.parent.create(f.f.f.key()).study();var outside=f.f.parent.parent.create(f.f.f.key()).study();UUID bTask=task(b.studyId()),outTask=task(outside.studyId());var answer=f.f.store.submit(f.f.group,f.f.space,b.studyId(),bTask,f.f.author,0,2,f.f.f.key(),"PRIVATE B ANSWER",f.f.f.trace).submission();f.f.store.submit(f.f.group,f.f.space,outside.studyId(),outTask,f.f.author,0,2,f.f.f.key(),"EXCLUDED",f.f.f.trace);f.f.store.submit(f.f.group,f.f.space,b.studyId(),bTask,f.f.f.owner,0,2,f.f.f.key(),"EXCLUDED OWNER SELF",f.f.f.trace);task(b.studyId());assertEquals(1,list("ALL",null,100).items().size());var c=courses.curriculum(f.f.group,f.f.space,course,f.f.f.owner,2,List.of(f.f.study,b.studyId()),f.f.f.trace);assertEquals(2,list("ALL",null,100).items().size());assertTrue(list("ALL",null,100).items().stream().noneMatch(v->v.studyId().equals(outside.studyId())||v.authorId().equals(f.f.f.owner)));
  f.f.parent.parent.store.metadata(f.f.group,f.f.space,b.studyId(),f.f.f.owner,1,"Current B <script>","New",f.f.f.trace);f.f.parent.store.metadata(f.f.group,f.f.space,b.studyId(),bTask,f.f.f.owner,2,"Current task <script>","Changed instructions",f.f.f.trace);var row=list("ALL",null,100).items().stream().filter(v->v.submissionId().equals(answer.submissionId())).findFirst().orElseThrow();assertEquals("Current B <script>",row.studyTitle());assertEquals("Current task <script>",row.assignmentTitle());assertEquals(2,row.assignmentVersion());assertEquals(b.title(),courses.get(f.f.group,f.f.space,course).studies().get(1).title());
  c=courses.curriculum(f.f.group,f.f.space,course,f.f.f.owner,c.version(),List.of(b.studyId()),f.f.f.trace);assertEquals(List.of(answer.submissionId()),list("ALL",null,100).items().stream().map(CourseGradingQueueStore.Row::submissionId).toList());c=courses.state(f.f.group,f.f.space,course,f.f.f.owner,c.version(),"RETIRED",f.f.f.trace);f.f.parent.parent.store.state(f.f.group,f.f.space,b.studyId(),f.f.f.owner,2,"RETIRED",f.f.f.trace);int events=f.f.f.jdbc.queryForObject("SELECT count(*) FROM outbox_event",Integer.class);for(String filter:CourseGradingQueueStore.FILTERS)list(filter,null,20);assertEquals("RETIRED",list("ALL",null,20).items().getFirst().courseState());assertEquals(0,f.f.f.jdbc.queryForObject("SELECT count(*) FROM course_enrollment WHERE course_id=?",Integer.class,course));assertEquals(events,f.f.f.jdbc.queryForObject("SELECT count(*) FROM outbox_event",Integer.class));
 }
 @Test void filteringPrecedesLimitAcrossStudiesAssignmentsAndAuthors(){
  var b=f.f.parent.parent.create(f.f.f.key()).study();courses.curriculum(f.f.group,f.f.space,course,f.f.f.owner,2,List.of(f.f.study,b.studyId()),f.f.f.trace);for(int n=0;n<12;n++){UUID study=n%2==0?f.f.study:b.studyId(),assignment=task(study);for(int m=0;m<2;m++){var answer=f.f.store.submit(f.f.group,f.f.space,study,assignment,f.f.f.ids.next(),0,2,f.f.f.key(),"PRIVATE ANSWER",f.f.f.trace).submission();if(m==0)f.store.change(f.f.group,f.f.space,study,assignment,answer.submissionId(),f.f.f.owner,0,new SubmissionGradeInput(0,"PRIVATE reason",1,2),f.f.f.trace);}}assertEquals(25,list("ALL",null,100).items().size());assertEquals(12,list("CURRENT",null,100).items().size());assertEquals(13,list("NEEDS_GRADING",null,100).items().size());var seen=new ArrayList<UUID>();UUID after=null;do{var p=list("CURRENT",after,3);seen.addAll(p.items().stream().map(CourseGradingQueueStore.Row::submissionId).toList());after=p.nextAfter();}while(after!=null);assertEquals(list("CURRENT",null,100).items().stream().map(CourseGradingQueueStore.Row::submissionId).toList(),seen);assertEquals(12,new HashSet<>(seen).size());
 }
}
